# src/crashload/dataio.pyfrom __future__ import annotationsimport globimport pandas as pddef load_universe(path: str | None = None) -> pd.DataFrame:    """    Load the frozen S&P 500 snapshot.    If `path` is None, use the newest file under data/universe/.    """    if path is None:        files = sorted(glob.glob("data/universe/sp500_*.csv"))        if not files:            raise FileNotFoundError("No universe CSV found under data/universe/.")        path = files[-1]    df = pd.read_csv(path)    for col in ("ticker", "name", "sector"):        if col in df.columns:            df[col] = df[col].astype(str).str.strip()    return df